// Token decimals
export const USDC_DECIMALS = 6
export const JESSE_DECIMALS = 18

// Token configuration
export const TOKENS = {
  USDC: {
    symbol: 'USDC',
    decimals: USDC_DECIMALS,
    addresses: USDC_ADDRESSES,
  },
  JESSE: {
    symbol: 'JESSE',
    decimals: JESSE_DECIMALS,
    addresses: {
      [CHAIN_IDS.BASE]: BASE_JESSE,
    },
  },
} as const

export interface TokenMetadata {
  symbol: string;
  decimals: number;
  isStable: boolean;
}

export const TOKEN_METADATA: Record<string, TokenMetadata> = {
  // Base USDC
  [USDC_ADDRESSES[CHAIN_IDS.BASE].toLowerCase()]: {
    symbol: 'USDC',
    decimals: 6,
    isStable: true,
  },
  // Arbitrum USDC
  [USDC_ADDRESSES[CHAIN_IDS.ARBITRUM].toLowerCase()]: {
    symbol: 'USDC',
    decimals: 6,
    isStable: true,
  },
  // Base JESSE
  [BASE_JESSE.toLowerCase()]: {
    symbol: 'JESSE',
    decimals: 18,
    isStable: false,
  },
};

export const formatPrize = (tokenAddress: string | undefined, rawPrize: bigint): string => {
  if (!tokenAddress) return formatUSDC(rawPrize); // Default fallback

  const metadata = TOKEN_METADATA[tokenAddress.toLowerCase()];
  if (!metadata) {
    // Fallback for unknown tokens, assume 18 decimals and show raw amount
    return `${formatTokenAmount(rawPrize, 18)} TOKEN`;
  }

  const formatted = formatUnits(rawPrize, metadata.decimals);

  if (metadata.isStable) {
    return `$${formatted}`;
  } else {
    return `${formatted} ${metadata.symbol}`;
  }
};

// Convert human readable amount to wei
export const parseTokenAmount = (amount: string | number, decimals: number): bigint => {
  const num = typeof amount === 'string' ? parseFloat(amount) : amount
  if (isNaN(num) || !isFinite(num) || num < 0) {
    return BigInt(0)
  }
  // Handle decimals carefully to avoid precision loss with floats
  const [integerPart, fractionalPart = ''] = String(num).split('.')
  const paddedFraction = fractionalPart.padEnd(decimals, '0').slice(0, decimals)
  return BigInt(`${integerPart}${paddedFraction}`)
}

// Convert wei to human readable amount
export const formatTokenAmount = (amount: bigint | string | number, decimals: number): string => {
  const value = typeof amount === 'bigint' ? amount : BigInt(amount)
  const divisor = BigInt(10) ** BigInt(decimals)
  const integerPart = value / divisor
  const fractionalPart = value % divisor
  const paddedFraction = fractionalPart.toString().padStart(decimals, '0')
  // Remove trailing zeros
  const formattedFraction = paddedFraction.replace(/0+$/, '')
  return formattedFraction ? `${integerPart}.${formattedFraction}` : `${integerPart}`
}

// Legacy helpers for backward compatibility (deprecate later)
export const parseUSDC = (amount: string | number) => parseTokenAmount(amount, USDC_DECIMALS)
export const formatUSDC = (amount: bigint | string | number) => formatTokenAmount(amount, USDC_DECIMALS)

